1	// Acceptance tests for the change request:
2	//   "I do not want to type one figure for an invoice. Let me list the things I am charging for.
3	//    For each one give a description, how many, and the price each. Work out the total for me."
4	//
5	// An invoice is now built up from the THINGS being charged for — line items. Opening an invoice
6	// (invoice-open-<id> from the all-invoices list, the same list-page drill-in convention as
7	// project-open / client-open) reaches that invoice's own detail page (invoice-detail-page). The
8	// detail page lists the line items in a table (invoice-lineitems-table); each row
9	// (lineitem-row-<id>) names the thing being charged for (lineitem-description), HOW MANY
10	// (lineitem-qty), the PRICE EACH (lineitem-unitprice) and the worked-out line amount
11	// (lineitem-amount = qty * unitprice). A form (lineitem-form) adds a new line item from those three
12	// fields (lineitem-form-description / -qty / -unitprice, submitted with lineitem-form-submit),
13	// rejecting an incomplete one with lineitem-form-error. The whole point — "work out the total for
14	// me" — is that the invoice's amount is the SUM of its line amounts, never a figure the user types;
15	// it is surfaced through the existing invoice-amount anchor on the all-invoices list.
16	//
17	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed, which honours
18	// invoices with a `lineItems` array whose elements carry { id, description, qty, unitPrice }.
19	// No `amount` is seeded on a line-item invoice: the total must be WORKED OUT from the lines, so
20	// seeding it would let a stored figure pass the test without the feature. (That is also why these
21	// tests must FAIL before the change: the pre-change seed has no line-item support and there is no
22	// invoice detail page.)
23	//
24	// Line amounts and unit prices are money; the three money-format anchors from money-format.spec are
25	// invoice-amount / project-invoices-total / dashboard-outstanding-total, so the invoice total is
26	// asserted exactly ("$400.00"), while the NEW lineitem-amount / lineitem-unitprice cells are matched
27	// leniently ($ and trailing .00 optional) since their exact presentation is not what this change
28	// pins. Quantities are whole counts. Values are chosen so no line amount is a substring of the total
29	// or of another line (300 / 100 / 400), and each cell is scoped to its row so a stray match cannot
30	// pass by accident.
31	import { test, expect } from '@playwright/test';
32	import { resetAndSeed } from '../support/seed';
33	
34	test.describe('an invoice is a list of things being charged for, with the total worked out', () => {
35	  test('opening an invoice lists each thing — description, how many, price each — with the total worked out', async ({ page }) => {
36	    await resetAndSeed({
37	      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
38	      projects: [{ id: 1, clientId: 1, name: 'Website redesign' }],
39	      invoices: [
40	        {
41	          id: 1,
42	          projectId: 1,
43	          status: 'DRAFT',
44	          // The things being charged for. No `amount` on the invoice: it is worked out from these.
45	          lineItems: [
46	            { id: 1, description: 'Design work', qty: 2, unitPrice: 150 }, // 2 * 150 = 300
47	            { id: 2, description: 'Hosting setup', qty: 4, unitPrice: 25 }, // 4 * 25  = 100
48	          ],
49	        },
50	      ],
51	    });
52	
53	    // The invoice's amount, surfaced on the all-invoices list, is the SUM of its lines (300 + 100),
54	    // worked out for the user — not a single figure they typed.
55	    await page.goto('/invoices');
56	    await expect(page.getByTestId('invoices-page')).toBeVisible();
57	    const listRow = page.getByTestId('invoice-row-1');
58	    await expect(listRow).toBeVisible();
59	    await expect(listRow.getByTestId('invoice-amount')).toHaveText('$400.00');
60	
61	    // Drill into the invoice to see what it is made of — a child route, reached via its open control.
62	    await listRow.getByTestId('invoice-open-1').click();
63	
64	    await expect(page.getByTestId('invoice-detail-page')).toBeVisible();
65	    await expect(page.getByTestId('invoice-lineitems-table')).toBeVisible();
66	
67	    // First thing: "Design work", 2 @ $150.00 each, worked out to $300.00.
68	    const first = page.getByTestId('lineitem-row-1');
69	    await expect(first).toBeVisible();
70	    await expect(first.getByTestId('lineitem-description')).toHaveText('Design work');
71	    await expect(first.getByTestId('lineitem-qty')).toHaveText(/^2(\.0+)?$/);
72	    await expect(first.getByTestId('lineitem-unitprice')).toHaveText(/^\$?150(\.00)?$/);
73	    await expect(first.getByTestId('lineitem-amount')).toHaveText(/^\$?300(\.00)?$/);
74	
75	    // Second thing: "Hosting setup", 4 @ $25.00 each, worked out to $100.00.
76	    const second = page.getByTestId('lineitem-row-2');
77	    await expect(second).toBeVisible();
78	    await expect(second.getByTestId('lineitem-description')).toHaveText('Hosting setup');
79	    await expect(second.getByTestId('lineitem-qty')).toHaveText(/^4(\.0+)?$/);
80	    await expect(second.getByTestId('lineitem-unitprice')).toHaveText(/^\$?25(\.00)?$/);
81	    await expect(second.getByTestId('lineitem-amount')).toHaveText(/^\$?100(\.00)?$/);
82	  });
83	
84	  test('adds a thing through the form; it appears with its worked-out amount and lifts the total', async ({ page }) => {
85	    // An invoice with nothing on it yet. RESTART IDENTITY on reset + an empty lineItems array means
86	    // the first line item added through the UI is id 1.
87	    await resetAndSeed({
88	      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
89	      projects: [{ id: 1, clientId: 1, name: 'Website redesign' }],
90	      invoices: [{ id: 1, projectId: 1, status: 'DRAFT', lineItems: [] }],
91	    });
92	
93	    // Nothing charged for yet, so the worked-out total is zero.
94	    await page.goto('/invoices');
95	    await expect(page.getByTestId('invoice-row-1').getByTestId('invoice-amount')).toHaveText('$0.00');
96	
97	    await page.getByTestId('invoice-row-1').getByTestId('invoice-open-1').click();
98	    await expect(page.getByTestId('invoice-detail-page')).toBeVisible();
99	    await expect(page.getByTestId('lineitem-form')).toBeVisible();
100	    // No line items seeded, so no rows yet.
101	    await expect(page.getByTestId('lineitem-description')).toHaveCount(0);
102	
103	    // List one thing being charged for: 3 hours @ $90.00 each.
104	    await page.getByTestId('lineitem-form-description').fill('Consulting');
105	    await page.getByTestId('lineitem-form-qty').fill('3');
106	    await page.getByTestId('lineitem-form-unit').fill('hours');
107	    await page.getByTestId('lineitem-form-unitprice').fill('90');
108	    await page.getByTestId('lineitem-form-submit').click();
109	
110	    // It appears as a row, its amount worked out for the user (3 * 90 = 270).
111	    const row = page.getByTestId('lineitem-row-1');
112	    await expect(row).toBeVisible();
113	    await expect(row.getByTestId('lineitem-description')).toHaveText('Consulting');
114	    await expect(row.getByTestId('lineitem-qty')).toHaveText(/^3(\.0+)?$/);
115	    await expect(row.getByTestId('lineitem-unit')).toHaveText('hours');
116	    await expect(row.getByTestId('lineitem-unitprice')).toHaveText(/^\$?90(\.00)?$/);
117	    await expect(row.getByTestId('lineitem-amount')).toHaveText(/^\$?270(\.00)?$/);
118	    // A valid add is not an error.
119	    await expect(page.getByTestId('lineitem-form-error')).toHaveCount(0);
120	
121	    // Back on the list, the invoice total now reflects the thing just added — worked out, not typed.
122	    await page.goto('/invoices');
123	    await expect(page.getByTestId('invoice-row-1').getByTestId('invoice-amount')).toHaveText('$270.00');
124	  });
125	
126	  test('refuses an incomplete line item, surfacing an error and adding nothing', async ({ page }) => {
127	    await resetAndSeed({
128	      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
129	      projects: [{ id: 1, clientId: 1, name: 'Website redesign' }],
130	      invoices: [{ id: 1, projectId: 1, status: 'DRAFT', lineItems: [] }],
131	    });
132	
133	    await page.goto('/invoices');
134	    await page.getByTestId('invoice-row-1').getByTestId('invoice-open-1').click();
135	
136	    await expect(page.getByTestId('invoice-detail-page')).toBeVisible();
137	    await expect(page.getByTestId('lineitem-form')).toBeVisible();
138	    // No error before the user tries anything.
139	    await expect(page.getByTestId('lineitem-form-error')).toHaveCount(0);
140	
141	    // Submitting an empty form (no description, no quantity, no price) cannot describe a thing to
142	    // charge for: it is rejected and nothing is created.
143	    await page.getByTestId('lineitem-form-submit').click();
144	
145	    await expect(page.getByTestId('lineitem-form-error')).toBeVisible();
146	    await expect(page.getByTestId('lineitem-row-1')).toHaveCount(0);
147	    await expect(page.getByTestId('lineitem-amount')).toHaveCount(0);
148	
149	    // A complete line item is then accepted, clearing the error and appearing as the first row (id 1).
150	    await page.getByTestId('lineitem-form-description').fill('Consulting');
151	    await page.getByTestId('lineitem-form-qty').fill('3');
152	    await page.getByTestId('lineitem-form-unit').fill('hours');
153	    await page.getByTestId('lineitem-form-unitprice').fill('90');
154	    await page.getByTestId('lineitem-form-submit').click();
155	
156	    const row = page.getByTestId('lineitem-row-1');
157	    await expect(row).toBeVisible();
158	    await expect(row.getByTestId('lineitem-amount')).toHaveText(/^\$?270(\.00)?$/);
159	    await expect(page.getByTestId('lineitem-form-error')).toHaveCount(0);
160	  });
161	});
